from pathlib import Path
from html import escape as e
import json

root = Path(__file__).resolve().parent
data = json.loads((root/'references.json').read_text(encoding='utf-8'))
cards=[]
for s in data['sites']:
    swatches=''.join(f'<span class="swatch"><i style="background:{c}"></i><code>{c}</code></span>' for c in s['palette'])
    cards.append(f'''<article class="reference" data-market="{s['market']}">
    <header><div><small>{'VIỆT NAM' if s['market']=='vn' else 'QUỐC TẾ'}</small><h2><a href="{s['url']}" target="_blank" rel="noopener noreferrer">{e(s['name'])} ↗</a></h2></div><a class="metric" href="{s['trafficUrl']}" target="_blank" rel="noopener noreferrer"><b>{s['displayVisits']}</b><span>lượt / tháng · 09.2026</span></a></header>
    <div class="screen"><img src="evidence/{s['id']}-desktop.png" data-id="{s['id']}" alt="Ảnh chụp giao diện {e(s['name'])}" loading="lazy" width="1440" height="1000"></div>
    <div class="card-body"><div class="swatches">{swatches}</div><p class="palette-note">{e(s['paletteNote'])}</p><p>{e(s['layout'])}</p><div class="takeaway"><strong>Điểm nên học</strong><p>{e(s['learn'])}</p></div><p class="adapt"><b>Áp dụng:</b> {e(s['adapt'])}</p><details><summary>Giới hạn và ảnh vùng dưới</summary><p>{e(s['caution'])}</p><a href="evidence/{s['id']}-desktop-lower.png" target="_blank"><img class="lower" src="evidence/{s['id']}-desktop-lower.png" alt="Vùng bên dưới của {e(s['name'])}" loading="lazy" width="1440" height="1000"></a></details></div></article>''')

palette=[('Xanh ngọc','#244638'),('Nền giấy','#F7F4EC'),('Mặt thẻ','#FFFEFA'),('Xanh nhẹ','#E7EDDF'),('Đồng trầm','#9A7137'),('Đỏ đất','#9E5142'),('Chữ chính','#26372E')]
proposed=''.join(f'<div><i style="background:{c}"></i><b>{n}</b><code>{c}</code></div>' for n,c in palette)
html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tham khảo giao diện · Huyền Học Các</title><style>
:root{color:#26372e;background:#f5f3ed;font:15px/1.7 'Segoe UI',Arial,sans-serif}*{box-sizing:border-box}body{margin:0}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}button{font:inherit;cursor:pointer}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #9a7137;outline-offset:4px}.wrap{width:min(1240px,calc(100% - 48px));margin:auto}.mast{padding:30px 0 20px;border-bottom:1px solid #d9ddcf;display:flex;justify-content:space-between;gap:20px;font-size:12px}.mast b{letter-spacing:1px}.intro{padding:42px 0 24px}.eyebrow{font-size:11px;color:#8b6b39;letter-spacing:2px}h1,h2,h3,p{margin:0}h1{font:42px/1.2 Georgia,serif;max-width:800px;margin:12px 0 20px}h1 em{color:#68805c}.lead{max-width:880px;color:#5f6c60;line-height:1.9}.note{font-size:12px;color:#6e786b;margin-top:14px;max-width:890px}.direction{background:#244638;color:#f9f6e9;padding:26px 30px;border-radius:8px;margin:12px 0 25px;display:grid;grid-template-columns:1fr 1.4fr;gap:35px}.direction h2{font:27px/1.4 Georgia,serif}.direction p{font-size:13px;line-height:1.9;color:#e5ebdd}.palette{display:grid;grid-template-columns:repeat(7,1fr);gap:12px;margin:20px 0 35px}.palette>div{min-width:0}.palette i{display:block;height:56px;border-radius:5px;border:1px solid #26372e18;margin-bottom:8px}.palette b,.palette code{display:block;font-size:11px}.palette code{color:#7a8172}.controls{display:flex;justify-content:space-between;gap:14px;flex-wrap:wrap;position:sticky;top:0;z-index:5;padding:15px 0;background:#f5f3edf5;backdrop-filter:blur(8px);border-bottom:1px solid #d9ddcf;margin-bottom:25px}.controls>div{display:flex;gap:5px;align-items:center}.controls button{border:1px solid #cfd5c5;border-radius:4px;padding:8px 13px;background:transparent;font-size:12px;color:#46603c}.controls button[aria-pressed=true]{background:#244638;color:#faf8ed;border-color:#244638}.controls span{font-size:11px;color:#6c7a65;margin-right:10px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;align-items:start}.reference{border:1px solid #d9ddcf;background:#fffefa;border-radius:8px;overflow:hidden}.reference>header{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:21px 22px;border-bottom:1px solid #e1e5d9}.reference small{font-size:9px;color:#8b6b39;letter-spacing:1.5px}.reference h2{font:24px/1.4 Georgia,serif}.metric{text-align:right;flex-shrink:0}.metric b{font-size:17px;display:block;font-weight:600}.metric span{font-size:9px;color:#78846e}.screen{background:#eeeee7;border-bottom:1px solid #d9ddcf;display:flex;justify-content:center;padding:12px}.screen img{display:block;width:100%;height:auto;box-shadow:0 2px 12px #26372e0c}.mobile .screen{height:560px;padding:14px;overflow:auto}.mobile .screen img{width:246px;height:auto;align-self:start;max-width:100%}.card-body{padding:22px}.swatches{display:flex;gap:14px;flex-wrap:wrap}.swatch{display:flex;align-items:center;gap:5px;font-size:10px}.swatch i{width:18px;height:18px;border-radius:50%;border:1px solid #0002}.palette-note{font-size:10px;color:#7d8775;margin:9px 0 17px}.card-body>p{font-size:12px;line-height:1.9}.takeaway{border-left:2px solid #9db088;padding:12px 14px;background:#edf2e6;margin:16px 0}.takeaway strong{font-size:11px}.takeaway p{font-size:12px;margin-top:3px}.adapt{color:#5c6d53;margin-bottom:16px}details{border-top:1px solid #e2e5d8;padding-top:12px;font-size:11px}summary{cursor:pointer;color:#8a6c38}details p{margin-top:12px;color:#7c806b}.lower{display:block;width:100%;height:auto;margin-top:14px}.bottom{border-top:1px solid #d9ddcf;margin:35px 0 25px;padding-top:23px;font-size:12px;color:#6f7d65}.bottom p{margin:10px 0}.bottom a{text-decoration:underline}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:30px 0}.step{border:1px solid #d9ddcf;padding:19px;background:#fffefa;border-radius:6px}.step b{font-size:12px}.step p{font-size:12px;color:#6a7861;margin-top:7px}[hidden]{display:none!important}@media(max-width:760px){.wrap{width:calc(100% - 28px)}h1{font-size:33px}.intro{padding-top:28px}.direction{grid-template-columns:1fr;gap:14px;padding:22px}.palette{grid-template-columns:repeat(4,1fr)}.grid{grid-template-columns:1fr}.controls{position:static}.reference>header{padding:18px}.metric b{font-size:15px}.reference h2{font-size:23px}.steps{grid-template-columns:1fr}.mast{font-size:10px}.mobile .screen{height:540px}}
</style></head><body><div class="wrap"><header class="mast"><b>HUYỀN HỌC CÁC / DESIGN RESEARCH</b><span>25.10.2026 · Tài liệu tham khảo riêng</span></header><section class="intro"><p class="eyebrow">BỐ CỤC · GIAO DIỆN · MÀU SẮC</p><h1>Học cách tổ chức tốt.<br><em>Giữ một cá tính riêng.</em></h1><p class="lead">Năm website có lưu lượng đáng kể trong mẫu khảo sát. Đã xem giao diện máy tính và điện thoại, đối chiếu số liệu truy cập cùng nguồn và cùng tháng. Trọng tâm: đưa tra cứu ra sớm, phân nhóm rõ và dùng hình ảnh có tiết chế.</p><p class="note">Số liệu Semrush, tháng 9/2026: tổng lượt truy cập ước tính toàn cầu trên mọi thiết bị, không phải người dùng duy nhất. Mẫu này không phải bảng xếp hạng toàn thị trường. Lưu lượng không chứng minh thiết kế tạo ra hiệu quả.</p></section><section class="direction"><h2>Hướng đề xuất<br>cho Huyền Học Các</h2><p>Tra cứu nhanh như Tra Cứu Tử Vi; phân nhóm như Astro.com; hệ minh họa và thẻ nội dung như Astrology.com. Giữ xanh ngọc, nền giấy và tranh riêng hiện tại. Tăng độ rõ của chữ và đưa biểu mẫu đến sớm hơn.</p></section><p class="eyebrow">BẢNG MÀU ĐỀ XUẤT RIÊNG CHO DỰ ÁN</p><div class="palette">'''+proposed+'''</div><div class="controls"><div aria-label="Lọc theo thị trường"><button data-filter="all" aria-pressed="true">Tất cả</button><button data-filter="vn" aria-pressed="false">Việt Nam</button><button data-filter="world" aria-pressed="false">Quốc tế</button></div><div aria-label="Chọn ảnh chụp"><span>Ảnh quan sát</span><button data-screen="desktop" aria-pressed="true">Máy tính</button><button data-screen="mobile" aria-pressed="false">Điện thoại</button></div></div><main class="grid">'''+''.join(cards)+'''</main><section class="steps"><article class="step"><b>01 · Đưa thao tác ra sớm</b><p>Rút gọn phần giới thiệu, năm công cụ có tên hành động và một câu mô tả. Nút chính dễ nhận ra, không cạnh tranh với nhiều lời mời khác.</p></article><article class="step"><b>02 · Màu nhấn có vai trò</b><p>Xanh đậm cho hành động, xanh nhẹ cho nhóm chủ đề. Đồng trầm và đỏ đất chỉ làm điểm nhấn nhỏ; nội dung dài dùng chữ đậm trên nền sáng.</p></article><article class="step"><b>03 · Giữ trang dễ đọc</b><p>Nội dung 15–16 px, đoạn vừa dài; ảnh ngoài biểu mẫu và kết quả. Nguồn nghiên cứu vẫn ở tài liệu riêng, không thêm vào trải nghiệm người dùng.</p></article></section><footer class="bottom"><p><b>Giới hạn quan sát:</b> Tuvi.vn trả 403 ở trình duyệt chụp ảnh nên không đưa hình thử thách vào phân tích. Một số trang có ảnh tải chậm hoặc vị trí quảng cáo trống; ảnh chụp không đại diện mọi người dùng.</p><p><b>Trạng thái:</b> Đây là bảng nghiên cứu, chưa đổi giao diện sản phẩm trong lượt khảo sát. Không sao chép ảnh, logo hoặc mã của trang tham khảo vào sản phẩm.</p><p><a href="REPORT.md">Báo cáo chi tiết</a> · <a href="references.json">Số liệu và URL</a> · <a href="evidence/capture-manifest.json">Nhật ký ảnh chụp</a> · <a href="https://www.semrush.com/semrush-questions/" target="_blank" rel="noopener noreferrer">Phương pháp ước tính</a></p></footer></div><script>
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.reference').forEach(x=>x.hidden=b.dataset.filter!=='all'&&x.dataset.market!==b.dataset.filter)});
document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{const mobile=b.dataset.screen==='mobile';document.querySelector('.grid').classList.toggle('mobile',mobile);document.querySelectorAll('[data-screen]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.screen img').forEach(img=>{img.src='evidence/'+img.dataset.id+'-'+b.dataset.screen+'.png';img.width=mobile?390:1440;img.height=mobile?844:1000})});
</script></body></html>'''
(root/'index.html').write_text(html, encoding='utf-8')
print('Built reference board:', len(cards), 'sites')
